import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import StatTile from 'views/admin/Common/StatTile';
import { fetchPeopleCountsService } from 'actions/admin/counts';
import { getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';

// A row of head-count cards for the students and staff lists: school students, the chosen class's students, school employees and
// the chosen class's teachers. `show` picks which cards appear; the two class cards need a `courseId`. `refreshKey` refetches
// (e.g. after a student is added). `extra` adds cards the page already knows, as [{ label, value, tone }].
const CARDS = {
  students: { label: 'School students', tone: 'info', total: 'totalStudents' },
  classStudents: { label: 'Class students', tone: 'good', byCourse: 'studentsByCourse' },
  employees: { label: 'School employees', tone: 'info', total: 'totalEmployees' },
  classEmployees: { label: 'Class teachers', tone: 'good', byCourse: 'teachersByCourse' },
};

const PeopleCountCards = ({ show = [], courseId, refreshKey, extra = [], style }) => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const [counts, setCounts] = useState(null);
  const [loading, setLoading] = useState(true);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const { batchId } = getGlobalCurrentBatchUtils();

  useEffect(() => {
    if (!schoolId || !token) {
      return undefined;
    }
    let cancelled = false;
    setLoading(true);
    fetchPeopleCountsService({ schoolId, batchId, token })
      .then(data => !cancelled && setCounts(data))
      .catch(() => !cancelled && setCounts(null))
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [schoolId, batchId, token, refreshKey]);

  // The counts are a nicety: when they cannot be fetched the page is shown without the cards rather than with empty ones.
  if (!loading && !counts) {
    return null;
  }

  const tiles = show
    .filter(key => CARDS[key] && (!CARDS[key].byCourse || courseId))
    .map(key => {
      const card = CARDS[key];
      const row = card.byCourse && (counts?.[card.byCourse] || []).find(item => `${item.id}` === `${courseId}`);
      return {
        key,
        label: row?.name && card.byCourse ? `${row.name} ${card.label.split(' ')[1]}` : card.label,
        tone: card.tone,
        value: card.total ? counts?.[card.total] : row?.count || 0,
      };
    });

  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 14, ...style }}>
      {tiles.map(tile => (
        <StatTile
          key={tile.key}
          label={tile.label}
          value={tile.value}
          tone={tile.tone}
          loading={loading}
          minWidth={150}
          maxWidth={240}
        />
      ))}
      {extra.map(item => (
        <StatTile
          key={item.label}
          label={item.label}
          value={item.value}
          tone={item.tone || 'neutral'}
          minWidth={150}
          maxWidth={240}
        />
      ))}
    </div>
  );
};

export default PeopleCountCards;
