import axios from 'axios';
import constants from 'config/constants';

// Head counts for the summary cards on the students and staff lists. Plain async call (no reducer): the cards fetch their own figures.
// -> { totalStudents, totalEmployees, totalTeachers, studentsByCourse: [{ id: courseId, name, count }], teachersByCourse: [...] }
// `teachersByCourse` lists only the classes that have a teacher, so a class that is missing there has none.
export const fetchPeopleCountsService = async ({ schoolId, batchId, token }) => {
  const res = await axios.get(
    `${constants.API_BASE_URL}/api/dashboard/total-users/counts${constants.makeParams({ schoolId, batchId })}`,
    constants.setHeader(token)
  );
  return res.data;
};
